public class SecureSSRFExample {
    public void makeRequest(String userInput) {
        try {
            // Validate that the URL is external and not pointing to internal services
            if (userInput == null || userInput.trim().isEmpty()) {
                System.out.println("Invalid URL provided.");
                return;
            }

            java.net.URL url = new java.net.URL(userInput);
            String host = url.getHost();

            // Check if the host is external and not internal (e.g., localhost, 127.0.0.1, etc.)
            if (host == null || isInternalHost(host)) {
                System.out.println("Request to internal host is not allowed.");
                return;
            }

            java.net.HttpURLConnection connection = (java.net.HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            int responseCode = connection.getResponseCode();
            System.out.println("Response Code: " + responseCode);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Helper method to check if a host is considered internal
